package com.anssa8bu.ssafy.event.entity; import com.anssa8bu.ssafy.common.entity.CreatedEntity; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant; import java.util.*; @Entity @Table(name="outbox_events") public class OutboxEvent extends CreatedEntity { @Id private UUID id; @Column(name="event_id",nullable=false,length=150) private String eventId; @Column(name="aggregate_type",nullable=false,length=100) private String aggregateType; @Column(name="aggregate_id",nullable=false,length=150) private String aggregateId; @Column(name="event_type",nullable=false,length=150) private String eventType; @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private Map<String,Object> payload; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private OutboxStatus status; @Column(nullable=false) private int attempt; @Column(name="available_at",nullable=false) private Instant availableAt; @Column(name="published_at") private Instant publishedAt; @Column(name="last_error",columnDefinition="text") private String lastError; protected OutboxEvent(){} public OutboxEvent(UUID id,String eventId,String aggregateType,String aggregateId,String eventType,Map<String,Object> payload,Instant availableAt){this.id=id;this.eventId=eventId;this.aggregateType=aggregateType;this.aggregateId=aggregateId;this.eventType=eventType;this.payload=Map.copyOf(payload);status=OutboxStatus.PENDING;this.availableAt=availableAt;} public UUID getId(){return id;} public Map<String,Object> getPayload(){return payload;} public OutboxStatus getStatus(){return status;} public Instant getPublishedAt(){return publishedAt;}}
